{
  "root": "main_stack",
  "state": {
    "travelContext": [
      {
        "key": "Dates",
        "value": "July 15, 2024 - July 24, 2024 (10 days, 9 nights)"
      },
      {
        "key": "Travelers",
        "value": "2 adults, 2 children (ages 8 and 12)"
      },
      {
        "key": "Budget",
        "value": "$4,000 USD for activities and food. This budget is assumed to cover daily excursions, entrance fees, local transportation, and all meals. Flights and accommodation are considered separate from this budget."
      },
      {
        "key": "Weather",
        "value": "July in Tokyo is typically hot and humid, with average temperatures around 25-30°C (77-86°F). Indoor activities and hydration breaks are incorporated."
      }
    ],
    "itinerary": [
      {
        "day": "Day 1",
        "icon": "../assets/r_000503_01_2_building.svg",
        "morningActivity": "Arrive at Narita (NRT) or Haneda (HND) Airport, transfer to your accommodation in Shinjuku. Settle in and relax after your journey.",
        "afternoonActivity": "Explore Shinjuku Gyoen National Garden, a beautiful oasis with Japanese, English, and French gardens, perfect for a leisurely stroll.",
        "dinnerSuggestion": "Casual dinner at a local ramen shop or a family-friendly restaurant in Shinjuku, perhaps near Shinjuku Station."
      },
      {
        "day": "Day 2",
        "icon": "../assets/r_000503_01_3_geo-alt.svg",
        "morningActivity": "Visit the Tokyo Metropolitan Government Building for free panoramic views of the city from its observation decks.",
        "afternoonActivity": "Immerse yourselves in the vibrant atmosphere of Shibuya Crossing, followed by a visit to the Hachiko statue. Explore Shibuya's shops and arcades.",
        "dinnerSuggestion": "Enjoy conveyor belt sushi for a fun and interactive dining experience."
      },
      {
        "day": "Day 3",
        "icon": "../assets/r_000503_01_5_star.svg",
        "morningActivity": "Full day at Tokyo Disneyland, enjoying classic attractions, parades, and shows suitable for all ages.",
        "afternoonActivity": "Continue exploring the park, focusing on rides and entertainment for both children and adults.",
        "dinnerSuggestion": "Theme park food and snacks throughout the day.",
        "actionLabel": "Tokyo Disneyland Tickets",
        "actionUrl": "https://www.tokyodisneyresort.jp/en/tdl/"
      },
      {
        "day": "Day 4",
        "icon": "../assets/r_000503_01_7_house.svg",
        "morningActivity": "Explore Asakusa, starting with the iconic Senso-ji Temple and Nakamise-dori Market for traditional snacks and souvenirs.",
        "afternoonActivity": "Visit Tokyo Skytree for breathtaking 360-degree views of the city. Explore the Solamachi shopping complex at its base.",
        "dinnerSuggestion": "Try Monjayaki (savory pancake) or Okonomiyaki in Asakusa."
      },
      {
        "day": "Day 5",
        "icon": "../assets/r_000503_01_9_book.svg",
        "morningActivity": "Journey to Mitaka for a pre-booked visit to the Ghibli Museum (book well in advance!).",
        "afternoonActivity": "Enjoy a relaxing walk and picnic lunch at Inokashira Park, adjacent to the Ghibli Museum, which also has a small zoo and paddle boats.",
        "dinnerSuggestion": "Casual dinner in Kichijoji, a lively area near Inokashira Park.",
        "actionLabel": "Ghibli Museum Info",
        "actionUrl": "https://www.ghibli-museum.jp/en/"
      },
      {
        "day": "Day 6",
        "icon": "../assets/r_000503_01_11_robot.svg",
        "morningActivity": "Take the Yurikamome line to Odaiba, a futuristic entertainment island. Visit TeamLab Planets (interactive digital art museum - book tickets in advance).",
        "afternoonActivity": "Explore the many attractions of Odaiba, such as the Gundam Base Tokyo, Joypolis (indoor amusement park), or Legoland Discovery Center. Enjoy views of Rainbow Bridge.",
        "dinnerSuggestion": "Dinner at one of Odaiba's many restaurants with waterfront views, offering a variety of cuisines."
      },
      {
        "day": "Day 7",
        "icon": "../assets/r_000503_01_13_tree.svg",
        "morningActivity": "Explore Ueno Park, home to several museums. Visit the Tokyo National Museum (oldest and largest museum in Japan) or the National Museum of Nature and Science.",
        "afternoonActivity": "Enjoy Ueno Zoo, famous for its pandas and diverse animal collection.",
        "dinnerSuggestion": "Try a local eatery in Ueno or explore the Ameya-Yokochō (Ameyoko) market for street food."
      },
      {
        "day": "Day 8",
        "icon": "../assets/r_000503_01_2_building.svg",
        "morningActivity": "Visit the Imperial Palace East Garden (the former site of Edo Castle) for a glimpse into Japan's imperial history.",
        "afternoonActivity": "Explore the upscale Ginza district. Window shop at luxury stores or visit the flagship stores of popular Japanese brands. Kids might enjoy a visit to a toy store like Hakuhinkan Toy Park.",
        "dinnerSuggestion": "Dinner in Ginza, ranging from casual to high-end, or explore the food halls of department stores for diverse options."
      },
      {
        "day": "Day 9",
        "morningActivity": "Take a day trip to Mount Takao, easily accessible from central Tokyo. Hike up the mountain (various trails available) or take the cable car/chair lift.",
        "afternoonActivity": "Enjoy the scenic views from the summit, visit the Takaosan Yakuoin Temple, and explore the monkey park.",
        "dinnerSuggestion": "Enjoy traditional soba noodles at a restaurant on Mount Takao or back in Shinjuku."
      },
      {
        "day": "Day 10",
        "icon": "../assets/r_000503_01_17_airplane.svg",
        "morningActivity": "Depending on your flight schedule, enjoy some last-minute souvenir shopping in your local area or revisit a favorite spot.",
        "afternoonActivity": "Transfer to Narita (NRT) or Haneda (HND) Airport for your departure.",
        "dinnerSuggestion": "A final Japanese meal at the airport or a local cafe before heading to the airport."
      }
    ]
  },
